insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('du-geesd-ma-voi-aum-geist', 'Du geesd ma voi aum Geist!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du gehst mir voll auf den Geist!', '[{"kategorie": "wörtlich", "text": "\"Du gehst mir voll auf die Nerven!\"  2. \"Du gehst mir voll auf den Zeiger!\"  3. \"Du [[zipfst]] mich an!\"  4. [[Du gehst mir auf die Eier!]]  5. [[Du gehst mir auf den Sack!]]  6. [[Du gehst mir auf den Keks!]]  6. [[Du geesd ma aum Zwicka!]]  7. [[Du geesd ma aum Wecka!]]"}]'::jsonb, ''),
  ('dea-schleimbeidl-geed-ma-uandlich-aufd-eia', 'Dea Schleimbeidl geed ma uandlich aufd Eia!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Dieser Schleimbeutel geht mir ordentlich auf die Eier!', '[{"kategorie": "wörtlich", "text": "\"Dieser Schleimbeutel geht mir tierisch auf den Sack!\"  2. \"Dieser Arschkriecher geht mir gehörig auf’n Senkel!\" 3. \"Dieser Schleimer geht mir mächtig auf den Zeiger!\""}]'::jsonb, ''),
  ('dea-geed-ma-aum-senkl', 'Dea geed ma aum Senkl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der geht mir auf den Senkel!', '[{"kategorie": "wörtlich", "text": "\"Der geht mir auf die Nerven!\" (\"Senkel\"=\"Schnürsenkel\"  - Bildlich: Wenn jemand „auf den Senkel tritt“, lockert sich der Schuh, man stolpert oder wird aufgehalten. Daraus entwickelte sich: „auf den Senkel gehen“ = jemandem unangenehm werden, nerven)"}, {"kategorie": "", "text": "\"Der geht mir auf den Geist!\"  3. \"Der geht mir auf den [[Keks]]!\"  4. \"Der geht mir auf den Sack!\"  5. \"Der geht mir auf die Eier!\"  6. [[Dea geed ma aum Zwicka!]]  7. [[Dea geed ma aum Zaaga!]]"}]'::jsonb, ''),
  ('a-gmaade-wiisn', 'A gmaade Wiisn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Eine gemähte Wiese!', '[{"kategorie": "fig.", "text": "\"Das reinste Kinderspiel!\"  2. \"Eine todsichere Sache!\"  3. \"Ein reiner Selbstläufer!\""}]'::jsonb, ''),
  ('des-is-fia-eam-a-gmaade-wiisn', 'Des is fia eam a gmaade Wiisn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist für ihn eine gemähte Wiese!', '[{"kategorie": "fig.", "text": "\"Das ist für ihn ein Kinderspiel!\"  2. \"Das ist für ihn eine todsichere Sache!\"  3. \"Das ist für ihn ein reiner Selbstläufer!\""}]'::jsonb, ''),
  ('do-is-da-hund-begroom', 'Do is da Hund begroom!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da ist der Hund begraben!', '[{"kategorie": "fig.", "text": "\"Da liegt der Fehler!\"  2. Da ist der Irrtum!  3. (Deutschland): \"Da liegt der Hase im Pfeffer\""}]'::jsonb, ''),
  ('in-iare-rosa-schuchaln-schaud-de-klaane-aus-wiara-prinzessin', 'In iare rosa Schuchaln schaud de Klaane aus wiara Prinzessin!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'In ihren rosa Schühchen sieht die Kleine aus wie ''ne Prinzessin!', '[{"kategorie": "wörtlich", "text": "\"Mit ihren rosa Schühchen sieht die Kleine echt prinzessinenhaft aus!\"  2. In den rosa Treterchen sieht die Kleine aus wie eine Märchenprinzessin!  3. Mit ihren rosa Söckchen und Schühchen wirkt die Kleine wie eine richtige Prinzessin!"}]'::jsonb, ''),
  ('an-schuach-mochn', 'an Schuach mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Schuh machen', '[{"kategorie": "wörtlich", "text": "\"einen Abgang machen\""}, {"kategorie": "", "text": "\"sich aus dem Staub machen\""}, {"kategorie": "", "text": "\"das Weite suchen\""}, {"kategorie": "Gaunersprache", "text": "\"aus dem Gefängnis ausbrechen\", fliehen, \"sich vom Acker machen\", [[päule]] gehen"}]'::jsonb, 'Ea woa nua drei Toog im Hääfn, daunn hoda an Schuach gmochd!'),
  ('ea-woa-nua-drei-toog-im-haeaefn-daunn-hoda-an-schuach-gmochd', 'Ea woa nua drei Toog im Hääfn, daunn hoda an Schuach gmochd!', '', '', '', 'Wiener Gaunersprache', 'Er war nur drei Tage im Häfen - dann hat er einen Schuh gemacht!', '[{"kategorie": "wörtlich", "text": "\"Er war nur drei Tage im Gefängnis - dann hat er sich vom Acker gemacht!\"  2. Er war nur drei Tage in Haft, dann ist er ausgebrochen!  3. Nach nur drei Tagen im Knast hat er einen gepflegten Abgang gemacht und ist geflohen!"}]'::jsonb, 'an Schuach mochn'),
  ('sei-oide-hod-an-schuach-gmochd-kaum-dassd-aufenthoidsgeneemigung-ghobd-hod', 'Sei Oide hod an Schuach gmochd, kaum dassd Aufenthoidsgeneemigung ghobd hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seine Alte hat einen Schuh gemacht, kaum dass sie die Aufenthaltsgenehmigung gehabt hat!', '[{"kategorie": "wörtlich", "text": "\"Seine Frau hat sich vom Acker gemacht, kaum dass sie den Aufenthaltstitel hatte!\"  2. Seine Alte hat ihn verlassen, sobald sie die Aufenthaltserlaubnis in der Tasche hatte!  3. Seine Ehefrau ist verduftet, kaum dass sie ihre Aufenthaltspapiere hatte!"}]'::jsonb, ''),
  ('i-moch-an-schuach', 'I moch an Schuach!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich mache einen Schuh!', '[{"kategorie": "wörtlich", "text": "\"Ich mache einen Abgang!\"  2. \"Ich mache mich auf den Weg!\"  3. \"Ich brech'' jetzt auf!\"  4. Ich mach mich aus dem Staub!  5. Ich verdufte jetzt!"}]'::jsonb, ''),
  ('neemd-schuach-schdee', 'neemd Schuach schdee', '', '', '', 'Wiener Sprüche, die sitzen!', 'neben den Schuhen stehen', '[{"kategorie": "wörtlich", "text": "\"neben sich stehen\""}, {"kategorie": "", "text": "\"den Boden unter den Füßen verlieren\""}, {"kategorie": "", "text": "\"von der Rolle sein\""}, {"kategorie": "", "text": "\"komplett neben der Spur sein\""}]'::jsonb, 'Seita hocknschdaad is, schdeeda komplett neemd Schuach!'),
  ('seita-hocknschdaad-is-schdeeda-komplett-neemd-schuach', 'Seita hocknschdaad is, schdeeda komplett neemd Schuach!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Seit er hackenstad ist, steht er komplett neben den Schuhen!', '[{"kategorie": "wörtlich", "text": "\"Seit er arbeitslos ist, steht er komplett neben sich!\"  2. Seit er ohne Job ist, hat er den Boden unter den Füßen verloren!\"  3. Seit er gekündigt wurde, ist er komplett von der Rolle!"}]'::jsonb, 'neemd Schuach schdee'),
  ('neemda-schbua-schdee', 'neemda Schbua schdee', '', '', '', 'Wiener Sprüche, die sitzen!', 'neben der Spur stehen', '[{"kategorie": "wörtlich", "text": "\"neben sich stehen\""}, {"kategorie": "", "text": "\"den Boden unter den Füßen verlieren\""}, {"kategorie": "", "text": "\"von der Rolle sein\""}, {"kategorie": "", "text": "[[neemd Schuach schdee]]"}]'::jsonb, ''),
  ('seit-sei-ex-wiida-gheirad-hod-schdeeda-komplett-neem-da-schbua', 'Seit sei Ex wiida gheirad hod, schdeeda komplett neem da Schbua!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit seine Ex wieder geheiratet hat, steht er komplett neben der Spur!', '[{"kategorie": "wörtlich", "text": "\"Seit seine Ex-Frau wieder geheiratet hat, steht er komplett neben sich!\"  2. Seit seine Ex-Frau einen anderen geheiratet hat, ist er komplett von der Rolle!  3. Er hat komplett den Boden unter den Füßen verloren, seit seine Ex-Frau wieder geheiratet hat!"}]'::jsonb, 'neemda Schbua schdee'),
  ('umgekead-wiada-schuach-draus', 'Umgekead wiada Schuach draus!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Umgekehrt wird ein Schuh draus!', '[{"kategorie": "wörtlich", "text": "\"Es ist genau andersherum!\"  2. \"Das Gegenteil ist richtig!\"  3. \"Dreh die Sache einfach um, dann stimmt''s!\"  4. \"Genau verkehrt rum ist''s richtig!\""}]'::jsonb, ''),
  ('si-an-weissn-schuach-mochn', 'si an weissn Schuach mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen weißen Schuh machen', '[{"kategorie": "wörtlich", "text": "\"einen sauberen Abgang hinlegen\""}, {"kategorie": "", "text": "\"sich aus der Verantwortung stehlen\""}, {"kategorie": "", "text": "\"sich eine weiße Weste bewahren\""}, {"kategorie": "", "text": "sich untadelig zeigen\""}, {"kategorie": "", "text": "\"sich elegant aus der Affäre ziehen\""}]'::jsonb, 'Noochn Chaos im Varein hoda si an weissn Schuach gmochd und is rechtzeitich zrucktreetn!'),
  ('noochn-chaos-im-varein-hoda-si-an-weissn-schuach-gmochd-und-is-rechtzeitich-zrucktreetn', 'Noochn Chaos im Varein hoda si an weissn Schuach gmochd und is rechtzeitich zrucktreetn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach dem Chaos im Verein hat er sich einen weißen Schuh gemacht und ist rechtzeitig zurückgetreten!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Chaos im Verein hat er einen sauberen Abgang hingelegt und ist rechtzeitig zurückgetreten!\"  2. Nach dem Durcheinander im Verein hat er sich elegant aus der Affäre gezogen und rechtzeitig das Handtuch geworfen!  3. Nach dem Aufruhr im Verein hat er sich still und leise aus der Verantwortung gestohlen und ist zurückgetreten!"}]'::jsonb, 'si an weissn Schuach mochn'),
  ('an-laungan-schuach-mochn', 'an laungan Schuach mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen langen Schuh machen', '[{"kategorie": "wörtlich", "text": "\"sich dünn machen\""}, {"kategorie": "", "text": "\"sich schnell vom Acker machen\""}, {"kategorie": "", "text": "\"verschwinden wie der Blitz\""}, {"kategorie": "", "text": "\"mit unbekanntem Ziel verreisen\""}, {"kategorie": "", "text": "\"für immer von der Bildfläche verschwinden\""}, {"kategorie": "", "text": "\"das Weite suchen und nie wieder zurückkommen\""}]'::jsonb, 'Den siechsd so schnöö ned wiida - dea hod an laungan Schuach gmochd und is längsd iwa olle Beag!'),
  ('den-siechsd-so-schnoeoe-ned-wiida-dea-hod-an-laungan-schuach-gmochd-und-is-laengsd-iwa-olle-beag', 'Den siechsd so schnöö ned wiida - dea hod an laungan Schuach gmochd und is längsd iwa olle Beag!', '', '', '', 'Wiener Gaunersprache', 'Den siehst du so schnell nicht wieder - der hat ’nen langen Schuh gemacht und is’ längst über alle Berge!', '[{"kategorie": "wörtlich", "text": "\"Den kriegst du so schnell nicht mehr zu Gesicht - der hat sich aus dem Staub gemacht, und zwar auf Nimmerwiedersehen!\"  2. Da kannst du lange warten, bis der wieder auftaucht - der hat sich längst dünn gemacht und ist über alle Berge!  3. Nach dem kannst du lange suchen - der hat Fersengeld gegeben und ist wie der Blitz verschwunden!"}]'::jsonb, 'an laungan Schuach mochn'),
  ('moch-an-laungan-schuach-oda-i-friss-di', 'Moch an laungan Schuach, oda I friss di!', '', '', '', 'Wiener Gaunersprache', 'Mach einen langen Schuh, oder ich friss dich!', '[{"kategorie": "wörtlich", "text": "\"Mach dich schnell vom Acker, sonst verspeis ich dich zum Frühstück!\"  2. Verschwinde wie der Blitz, bevor ich Gulasch aus dir mache!  3. Hau auf der Stelle ab und komm nie wieder, sonst mach ich Hackfleisch aus dir!"}]'::jsonb, ''),
  ('si-an-schlaunkn-fuass-mochn', 'si an schlaunkn Fuass mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen schlanken Fuß machen', '[{"kategorie": "wörtlich", "text": "\"sich aus dem Staub machen\""}, {"kategorie": "", "text": "\"das Weite suchen\""}, {"kategorie": "", "text": "\"einen sauberen Abgang hinlegen\""}, {"kategorie": "", "text": "\"sich still und leise aus der Verantwortung stehlen\""}, {"kategorie": "", "text": "\"sich elegant aus der Affäre ziehen\""}, {"kategorie": "", "text": "\"sich vom Acker machen\""}]'::jsonb, 'Kaum brennd de Hittn, mochda si an schlaunkn Fuass!'),
  ('kaum-brennd-de-hittn-mochda-si-an-schlaunkn-fuass', 'Kaum brennd de Hittn, mochda si an schlaunkn Fuass!', '', '', '', 'Wiener Gaunersprache', 'Kaum brennt die Hütte, macht er sich einen schlanken Fuß!', '[{"kategorie": "wörtlich", "text": "\"Kaum ist Feuer am Dach ist, sucht er das Weite!\"  2. Kaum wird''s ungemütlich, macht er sich vom Acker!  3. Kaum fliegen die Fetzen, sieht man nur noch seine Rücklichter!"}]'::jsonb, 'si an schlaunkn Fuass mochn'),
  ('si-d-schuach-schmiian', 'si d''Schuach schmiian', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich die Schuhe schmieren', '[{"kategorie": "wörtlich", "text": "\"sich die Schuhe polieren\""}, {"kategorie": "scherzhaft für", "text": "sich fertigmachen zum Ausgehen"}, {"kategorie": "", "text": "außer Haus gehen"}]'::jsonb, 'Nau daunn schmiia ma uns amoi de Schuach - und daunn geeds auf de Piasch!'),
  ('nau-daunn-schmiia-ma-uns-amoi-de-schuach-und-daunn-geeds-auf-de-piasch', 'Nau daunn schmiia ma uns amoi de Schuach - und daunn geeds auf de Piasch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Na dann schmieren wir uns mal die Schuhe - und dann geht''s auf die Pirsch!', '[{"kategorie": "wörtlich", "text": "\"Na dann polieren wir uns mal die Schuhe - und dann geht''s auf die Pirsch!\"  2. Na gut – dann machen wir uns mal schick und schauen, was der Abend noch so alles bringt!  3. Lack auf die Schuhe, Grinsen ins Gesicht – los geht’s, rein in die Nacht!"}]'::jsonb, 'si d''Schuach schmiian'),
  ('ka-brood-aufd-schuach-haum', 'ka Brood aufd Schuach haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'kein Brot auf den Schuhen haben', '[{"kategorie": "wörtlich", "text": "\"ohne Brot und Arbeit sein\""}, {"kategorie": "", "text": "\"ohne Dach und Brot sein\""}, {"kategorie": "", "text": "\"mit leeren Taschen durchs Leben gehen\""}, {"kategorie": "", "text": "in Armut wandeln wie auf rohen Sohlen"}, {"kategorie": "", "text": "Not leiden, in Not sein, in Armut leben"}]'::jsonb, 'Waunnst ka Brood aufd Schuach host, bist im Oasch!'),
  ('waunnst-ka-brood-aufd-schuach-host-bist-im-oasch', 'Waunnst ka Brood aufd Schuach host, bist im Oasch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du kein Brot auf den Schuhen hast, bist du im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Wenn du ohne Brot und Arbeit bist, sitzt du in der Scheiße!\"  2. Wenn du nicht mehr genug zum Leben hast, bist du verloren!  3. Wenn du kein Geld hast und Not leidest, bist du nicht mal mehr Staub unter den Füßen der Reichen!"}]'::jsonb, 'ka Brood aufd Schuach haum'),
  ('des-intaressiad-mi-so-vue-wiara-schaas-im-woid', 'Des intaressiad mi so vü wiara Schaas im Woid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das interessiert mich so viel wie ein Schas im Wald!', '[{"kategorie": "wörtlich", "text": "\"Das interessiert mich nicht die Bohne!\"  2. \"Das geht mir am Allerwertesten vorbei!\"  3. \"Das interessiert mich einen feuchten Kehricht!  4. [[Des geed ma aum Oasch vuabei!]]"}]'::jsonb, ''),
  ('si-wos-in-oasch-schdeckn-kenna', 'si wos in Oasch schdeckn kenna', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich etwas in den Arsch stecken können', '[{"kategorie": "wörtlich", "text": "\"sich etwas hinten reinstecken können!\"  2. \"sich etwas sonstwohin stecken können!\"  3.  [[sich etwas hinten einführen können!]]  4. \"sich etwas auf den Nabel picken können!\""}]'::jsonb, 'Seine gschissanan Ausreedn kaunna si in Oasch schdeckn!'),
  ('des-kaunnst-da-in-oasch-schdeckn', 'Des kaunnst da in Oasch schdeckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das kannst du dir in den Arsch stecken', '[{"kategorie": "wörtlich", "text": "\"Das kannst du dir hinten reinstecken!\"  2. \"Das kannst du dir sonstwohin stecken!\"  3.  [[Das kannst du dir einführen!]]  4. \"Das kannst du dir auf den Nabel picken!\""}]'::jsonb, ''),
  ('seine-gschissanan-ausreedn-kaunna-si-in-oasch-schdeckn', 'Seine gschissanan Ausreedn kaunna si in Oasch schdeckn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Seine beschissenen Ausreden kann er sich in den Arsch stecken!', '[{"kategorie": "wörtlich", "text": "\"Seine Scheiß-Ausreden kann er sich sonstwohin stecken!\"  2. \"Seine miesen Ausreden kann er sich gepflegt hinten einführen!\"  3. \"Seine verlogenen Sprüche kann er sich auf den Nabel picken!\""}]'::jsonb, 'si wos in Oasch schdeckn kenna'),
  ('wem-vaoaschn', 'wem vaoaschn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden verarschen', '[{"kategorie": "wörtlich", "text": "\"jemanden verarschen\" (vom mittelhochdeutschen \"ars\"=\"Arsch\")"}, {"kategorie": "allg.", "text": "jemanden lächerlich machen, bloßstellen, zum Narren halten, auf den Arm nehmen, (Deutschland): \"veräppeln\""}, {"kategorie": "fig.", "text": "jemanden anschmieren, betrügen, hinters Licht führen, für dumm verkaufen"}]'::jsonb, 'Wüüsd mi vaoaschn oda maansd des eanst?'),
  ('wueuesd-mi-vaoaschn-oda-maansd-des-eanst', 'Wüüsd mi vaoaschn oda maansd des eanst?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Willst du mich verarschen oder meinst du das ernst?', '[{"kategorie": "wörtlich", "text": "\"Willst du mich auf den Arm nehmen, oder meinst du das ernst?\"  2. \"Machst du Witze, oder ist das dein Ernst?\"  3. \"Hältst du mich gerade zum Narren, oder meinst du das verdammt nochmal ernst?\""}]'::jsonb, 'wem vaoaschn'),
  ('vaoaschn-kaunnst-wem-aundan', 'Vaoaschn kaunnst wem aundan!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Verarschen kannst du jemand anderen!', '[{"kategorie": "wörtlich", "text": "\"Verscheißern kannst du jemand anderen!\"  2. \"Ich lass mich von dir doch nicht verschaukeln!\"  3. \"Erzähl das den Tauben im Park!\"  4. \"Lüg jemand anderen an, aber nicht mich!\""}]'::jsonb, 'wem vaoaschn'),
  ('des-geed-ma-aum-oasch', 'Des geed ma aum Oasch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht mir auf den Arsch!', '[{"kategorie": "wörtlich", "text": "\"Das geht mir tierisch auf die Nerven!\"  2. \"Das geht mir so dermaßen auf den Sack, ich könnt kotzen!\"  3. \"Das geht mir narrisch auf den [[Senkel]]!\"  4. \"Das nervt und ärgert mich ungemein!\""}]'::jsonb, ''),
  ('des-geed-ma-deamaassn-aum-oasch-dass-i-scho-haemorrhoidn-kriag', 'Des geed ma deamaassn aum Oasch, dass I scho Hämorrhoid’n kriag!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das geht mir dermaßen auf den Arsch, dass ich schon Hämorrhoiden krieg!', '[{"kategorie": "wörtlich", "text": "\"Das geht mir tierisch auf den Arsch wie ein Zapfen im Gesäß!\"  2. \"Das geht mir so sehr auf den Sack, dass mir bald die Eier platzen!\"  3. \"Das geht mir ärger auf den Arsch als drei Tage Scheißerei!"}]'::jsonb, 'Des geed ma aum Oasch!'),
  ('dea-trottl-geed-ma-deamaassn-aum-oasch-dass-i-scho-haemorrhoidn-kriag', 'Dea Trottl geed ma deamaassn aum Oasch, dass I scho Hämorrhoid’n kriag!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Trottel geht mir dermaßen auf den Arsch, dass ich schon Hämorrhoiden krieg!', '[{"kategorie": "wörtlich", "text": "\"Dieser Idiot geht mir auf den Arsch wie ein Zapfen im Gesäß!\"  2. \"Dieser Depp geht mir so sehr auf den Sack, dass mir bald die Eier platzen!\"  3. \"Dieser schwindliche Dillo geht mir auf den Arsch wie drei Tage Scheißerei!"}]'::jsonb, 'Dea geed ma aum Oasch!'),
  ('dea-deppade-dillo-geed-ma-aum-oasch-wia-drei-toog-scheissarei', 'Dea deppade Dillo geed ma aum Oasch wia drei Toog Scheissarei!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser depperte Dillo geht mir auf den Arsch wie drei Tage Scheißerei!', '[{"kategorie": "wörtlich", "text": "\"Dieser bekloppte Idiot geht mir auf den Arsch wie drei Tage Durchfall!\"  2. \"Dieser dämliche Trottel geht mir dermaßen auf den Arsch, dass ich schon Hämorrhoiden krieg!\"  3. \"Dieser Idiot geht mir auf den Arsch wie ein Zapfen im Gesäß!\"  4. \"Dieser Depp geht mir so sehr auf den Sack, dass mir bald die Eier platzen!\"  3."}]'::jsonb, ''),
  ('dea-depp-geed-ma-deamoosn-aum-sock-dass-ma-boid-de-eia-plotzn', 'Dea Depp geed ma deamoosn aum Sock, dass ma boid de Eia plotzn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Depp geht mir dermaßen auf den Sack, dass mir bald die Eier platzen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Vollidiot geht mir so auf die Eier, dass ich gleich explodiere!\"  2. \"Dieser dämliche Trottel geht mir dermaßen auf den Arsch, dass ich schon Hämorrhoiden krieg!\"  3. \"Dieser Vollpfosten geht mir auf den Arsch wie drei Tage Durchfall!\""}]'::jsonb, ''),
  ('wem-aum-oasch-vuabeigee', 'wem aum Oasch vuabeigee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden am Arsch vorbeigehen', '[{"kategorie": "wörtlich", "text": "\"jemandem am Allerwertesten vorbeigehen\""}, {"kategorie": "", "text": "\"jemanden nicht im Geringsten kümmern\""}, {"kategorie": "", "text": "\"jemanden nicht die Bohne interessieren\""}, {"kategorie": "", "text": "\"jemanden einen feuchten Kehricht interessieren\""}, {"kategorie": "", "text": "\"jemanden so viel interessieren wie ein Schas im Wald\""}]'::jsonb, 'Des geed ma aum Oasch vuabei!'),
